mapper.select:
		select 
			c.classroom_no,
			c.classroom_name,
			c.classroom_capacity,
			c.classroom_status
		from classroom c
		where c.classroom_status in ('사용가능', '사용중')

		and c.classroom_capacity >= #{courseLimit}


			and not exists (
				select 1
				from schedule s
				where s.classroom_no = c.classroom_no
				and (

						(
							s.schedule_week = #{schedule.scheduleWeek}

                            and s.schedule_start  < 
                                #{schedule.scheduleEnd}

                            and s.schedule_end  > 
                                #{schedule.scheduleStart}

                            and (
                                s.schedule_open is null
                                or #{schedule.scheduleClose} is null
                                or s.schedule_open  <= 
                                   #{schedule.scheduleClose}
                            )

                            and (
                                s.schedule_close is null
                                or #{schedule.scheduleOpen} is null
                                or s.schedule_close  >= 
                                   #{schedule.scheduleOpen}
                            )
						)

				)
			)

		order by c.classroom_no asc

select count(*)
from classroom
where classroom_no = #{classroomNo}

and classroom_status = '사용가능'
and classroom_capacity >= #{courseLimit}
